 s.code={0xBEEB03FF,0xBF810000};s.user_data.resize(16,0xDEADBEEF);s.flat=s.user_data;s.flat.insert(s.flat.end(),{11,22,33,44});s.flat_dwords=s.flat.size();s.walker={1,6,0,4,0,16,4,1,17,4,2,18,4,3,19,3,0,0,0,0,0};
 s.fetch.emplace();s.fetch->size=32;s.fetch->vertex_offset_sgpr=-1;s.fetch->instance_offset_sgpr=5;s.fetch->attributes.push_back({0,4,3,2,0,0,7,11,4});Shader::CompileSnapshot::RegisterRead read;read.pointer_index=2;read.dword_offset=0;std::array<uint32_t,4>words{0x12345678,0x87654321,8,0x123abcde};memcpy(&read.buffer,words.data(),16);s.register_reads.push_back(read);return s;
