std::vector<std::byte>Bytes(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);std::string s((std::istreambuf_iterator<char>(f)),{});std::vector<std::byte>b(s.size());memcpy(b.data(),s.data(),s.size());return b;}
